<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class muser extends CI_Controller {    private $limit = 10;    public function __construct() {        parent::__construct();        error_reporting(E_ALL);        $this->load->model('cadmin/musermodel');        $this->load->model('commonmodel');        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => 0, 'VarNew' => 0,            'ArrStates' => $this->commonmodel->getIndStates());        $VarUserId = base64_decode(urldecode($this->uri->segment(4)));        if ($VarUserId <> '' && $VarUserId > 0) {            $ArrResults              = $this->musermodel->fnGetUserInfo($VarUserId, 1);            $ArrData['ArrBasicInfo'] = $ArrResults;            $ArrData['VarId']     = $ArrResults->id;            $ArrData['VarCompId'] = $ArrResults->companyid;            $ArrData['userstate'] = $this->commonmodel->getIndStates($ArrResults->state);        } else {            $ArrData['VarNew'] = 1;        }        $this->load->view(CNFCADMIN . 'addedituser', $ArrData);    }    public function updateUserInfo() {        $ArrResult = array();        $VarfrmBasicName = xssclean($this->input->post('frmBasicName'));        $VarfrmBasicMob = xssclean($this->input->post('frmBasicMob'));        $VarfrmBasicCty = xssclean($this->input->post('frmBasicCty'));        $VarfrmBasicState = xssclean($this->input->post('frmBasicState'));        //$VarfrmBasicConty       											= xssclean($this->input->post('frmBasicConty'));        $VarId = xssclean($this->input->post('id'));        $CompId = xssclean($this->input->post('CompId'));        $VarLoggedUser = fnGetUserLoggedInfo();        if ($VarfrmBasicName <> '') {            $ArrUpdateData = array('id' => $VarId, 'contactname' => $VarfrmBasicName,                'mobile' => $VarfrmBasicMob, 'companyid' => $CompId, 'state' => $VarfrmBasicState, 'city' => $VarfrmBasicCty,                'dateupdated' => date('Y-m-d H:i:s'), 'updatedby' => $VarLoggedUser);            $ArrStatus = $this->musermodel->saveUserInfo($ArrUpdateData);            echo json_encode($ArrStatus);            unset($ArrStatus);            unset($ArrUpdateData);            die;        } else {            $ArrResult['errcode'] = '-1';            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manageuser() {        $VarFrom  = xssclean($this->input->post('rfrom'));        $VarEmail = xssclean($this->input->post('frmSrchEm'));        $VarCompName = xssclean($this->input->post('cn'));        $VarMobile = xssclean($this->input->post('frmSrchMob'));        $VarCity = xssclean($this->input->post('frmSrchCty'));        $VarState = xssclean($this->input->post('frmSrchState'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $VarAfilter = xssclean($this->input->post('afilter'));        $ArrDbCols = array('u.contactname', 'c.companyname', 'u.username', 'c.mobile', 'c.city', 'c.state', 'c.country', 'u.status', 'u.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCADMIN . 'muser/manageuser/';            $config['total_rows'] = $this->musermodel->fnCountUser($VarEmail, $VarCompName, $VarMobile, $VarCity, $VarState, $VarStatus, $VarAfilter);            $config['per_page'] = 10;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrUserList = $this->musermodel->fnListUser($VarEmail, $VarCompName, $VarMobile, $VarCity, $VarState,                $VarStatus, $this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('User');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrUserList as $ObjUnit) {                $ArrFnlList[$i]['id'] = $ObjUnit->id;                $ArrFnlList[$i]['email'] = $ObjUnit->username;                $ArrFnlList[$i]['n'] = $ObjUnit->contactname;                $ArrFnlList[$i]['compname'] = $ObjUnit->companyname;                $ArrFnlList[$i]['m'] = $ObjUnit->mobile;                $ArrFnlList[$i]['cty'] = $ObjUnit->city;                $ArrFnlList[$i]['state'] = $ObjUnit->state;                $ArrFnlList[$i]['pw'] = $ObjUnit->password;                $ArrFnlList[$i]['zp'] = $ObjUnit->zipcode;                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjUnit->dateupdated));                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjUnit->status];                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCADMIN . '/manageuser');        }    }    function delLabInfo() {        $VarLabId = xssclean($this->input->post('id'));        $VarUpdatedBy = fnGetUserLoggedInfo();        if ($VarLabId >= 1) {            $ArrResult = $this->mlabmodel->fnDelLab($VarLabId, $VarUpdatedBy);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = '';        }        echo json_encode($ArrResult);    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actdeactFabType'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->musermodel->fnChangeComStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1, 'msg' => 'Status Changed!'));        die;    }}